<?php $title = 'Anunciar imóvel'; ?><section class="container page-head"><p class="eyebrow">Cadastro gratuito</p><h1>Anunciar imóvel</h1><p>Seu anúncio será revisado antes de ser publicado.</p></section><section class="container form-card wide"><form method="post" enctype="multipart/form-data"><div class="form-row"><label>Finalidade<select name="finalidade" required><option value="venda">Venda</option><option value="aluguel">Aluguel</option></select></label><label>Tipo<select name="categoria_id" required><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= Helper::e($category['nome']) ?></option><?php endforeach; ?></select></label><label>Cidade<select name="cidade_id" required><?php foreach ($cities as $city): ?><option value="<?= (int) $city['id'] ?>"><?= Helper::e($city['nome']) ?>-<?= Helper::e($city['estado']) ?></option><?php endforeach; ?></select></label></div><div class="form-row"><label>Título<input name="titulo" required maxlength="180"></label><label>Preço<input type="number" name="preco" min="0" step="0.01" required></label></div><label>Bairro<input name="bairro"></label><label>Descrição<textarea name="descricao" rows="6" required></textarea></label><div class="form-row"><label>Quartos<input type="number" name="quartos" min="0" value="0"></label><label>Banheiros<input type="number" name="banheiros" min="0" value="0"></label><label>Suítes<input type="number" name="suites" min="0" value="0"></label><label>Vagas<input type="number" name="vagas" min="0" value="0"></label></div><div class="form-row"><label>Área construída<input type="number" name="area_construida" min="0" step="0.01"></label><label>Área do terreno<input type="number" name="area_terreno" min="0" step="0.01"></label></div><label>Endereço (opcional)<input name="endereco"></label><label>Características<textarea name="caracteristicas" rows="3"></textarea></label><div class="form-row"><label>Nome do anunciante<input name="nome_contato"></label><label>Telefone / WhatsApp<input name="telefone_contato"></label></div><label>Fotos (até 15, JPG, PNG ou WebP)<input type="file" name="fotos[]" accept="image/jpeg,image/png,image/webp" multiple></label><button class="button" type="submit">Enviar para aprovação</button></form></section>